import os
import re
import binascii
from pwn import *

def parse_commands(content):
    # Split into individual commands
    commands = content.split('\n')
    memory_ops = []
    file_ops = []
    locations = {}

    for cmd in commands:
        cmd = cmd.strip()
        if not cmd or cmd.startswith('#'):
            continue

        # Memory locations
        if cmd.startswith('f loc.'):
            loc_match = re.match(r'f\s+loc\.(\w+)\s*=\s*(0x[0-9a-f]+)', cmd)
            if loc_match:
                locations[loc_match.group(1)] = int(loc_match.group(2), 16)

        # Memory writes
        elif cmd.startswith('wx '):
            # Extract hex data and target
            wx_match = re.match(r'wx\s+([0-9a-f]+)(?:@(.+))?', cmd)
            if wx_match:
                hex_data = wx_match.group(1)
                target = wx_match.group(2) if wx_match.group(2) else 'current'
                try:
                    data = binascii.unhexlify(hex_data)
                    memory_ops.append(('write', target, data))
                except:
                    continue

        # File operations
        elif '/tmp/' in cmd:
            file_match = re.search(r'/tmp/([A-Z0-9]+)', cmd)
            if file_match:
                file_ops.append(file_match.group(1))

    return memory_ops, file_ops, locations

def analyze_operations(content):
    memory_ops, file_ops, locations = parse_commands(content)

    print("[+] Key memory locations:")
    for name, addr in locations.items():
        print(f"  {name} @ {hex(addr)}")

    print("\n[+] Memory operations:")
    for op, target, data in memory_ops:
        print(f"\n[+] {op.upper()} to {target}:")
        print(hexdump(data))

        # Look for flag patterns in the data
        try:
            decoded = data.decode('utf-8', errors='ignore')
            if 'flag{' in decoded or 'flag' in decoded:
                print(f"[!] Possible flag pattern in data: {decoded}")
        except:
            pass

    print("\n[+] Temporary files created:")
    unique_files = set(file_ops)
    for f in unique_files:
        print(f"  - {f}")

    # Analyze commands for process sequence
    print("\n[+] Operation sequence analysis:")
    cmd_sequence = []
    for line in content.split('\n'):
        if line.startswith('pc'):  # Process command
            pc_match = re.search(r'pc\*\s+(.+?)@(.+)', line)
            if pc_match:
                cmd_sequence.append((pc_match.group(1), pc_match.group(2)))

    if cmd_sequence:
        print("Found command sequence:")
        for cmd, target in cmd_sequence:
            print(f"  {cmd} -> {target}")

def main():
    try:
        with open('ctf_files/welcome2.r2', 'rb') as f:
            content = f.read().decode('utf-8', errors='ignore')
        analyze_operations(content)
    except Exception as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
from pwn import *
import os
import re
import binascii
import tempfile
import shutil

def parse_r2_script(script_path):
    with open(script_path, 'r') as f:
        script = f.read()

    # Parse memory locations
    memory_locs = {}
    commands = []
    current_addr = None

    for line in script.split('\n'):
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if line.startswith('f loc.'):
            parts = line.split('=')
            if len(parts) == 2:
                loc_name = parts[0].strip().split('.')[-1]
                addr = int(parts[1].strip(), 16)
                memory_locs[loc_name] = addr
                print(f"[+] Found memory location: {loc_name} @ {hex(addr)}")

        elif line.startswith('wx '):
            # Track hex writes
            data = line[3:].split('@')[0].strip()
            target = line.split('@')[1] if '@' in line else None
            commands.append(('wx', data, target))

        elif line.startswith('wr '):
            # Track raw writes
            data = line[3:].split('@')[0].strip()
            target = line.split('@')[1] if '@' in line else None
            commands.append(('wr', data, target))

        elif 'pc*' in line:
            # Track process commands
            src = re.search(r'loc\.flag\+([0-9]+)', line)
            if src:
                offset = int(src.group(1))
                tmp_file = re.search(r'/tmp/([A-Z0-9]+)', line)
                if tmp_file:
                    commands.append(('pc', offset, tmp_file.group(1)))

    return memory_locs, commands

def monitor_execution(script_path):
    # Setup monitoring
    memory_locs, commands = parse_r2_script(script_path)

    # Create temp monitoring directory
    tmp_dir = tempfile.mkdtemp()
    os.chmod(tmp_dir, 0o777)
    original_tmp = os.environ.get('TMPDIR')
    os.environ['TMPDIR'] = tmp_dir

    try:
        # Track memory contents
        memory = {}
        for name, addr in memory_locs.items():
            memory[name] = bytearray(b'\x00' * 0x1000)  # Allocate 4KB

        print("\n[+] Processing commands:")
        for cmd_type, *args in commands:
            if cmd_type == 'wx':
                data, target = args
                try:
                    hex_data = binascii.unhexlify(data)
                    if target:
                        loc_name = target.split('.')[1].split('+')[0]
                        offset = int(target.split('+')[1], 16) if '+' in target else 0
                        memory[loc_name][offset:offset+len(hex_data)] = hex_data

                    print(f"\n[+] WRITE to {target if target else 'current'}:")
                    print(hexdump(hex_data))

                    # Check for flag pattern
                    try:
                        decoded = hex_data.decode('ascii', errors='ignore')
                        if 'flag' in decoded.lower():
                            print(f"[!] Possible flag pattern in data: {decoded}")
                    except:
                        pass

                except Exception as e:
                    print(f"[-] Error processing wx command: {e}")

            elif cmd_type == 'pc':
                offset, tmp_file = args
                print(f"\n[+] Process command accessing flag+{offset} -> /tmp/{tmp_file}")

                # Monitor temp file
                tmp_path = os.path.join(tmp_dir, tmp_file)
                if os.path.exists(tmp_path):
                    with open(tmp_path, 'rb') as f:
                        data = f.read()
                        print(f"[+] Temp file content:")
                        print(hexdump(data))
                        try:
                            decoded = data.decode('ascii', errors='ignore')
                            if 'flag' in decoded.lower():
                                print(f"[!] Possible flag in temp file: {decoded}")
                        except:
                            pass

        # Final memory analysis
        print("\n[+] Final memory state:")
        for name, content in memory.items():
            if any(content):
                print(f"\n[+] Memory region {name}:")
                print(hexdump(content[:64]))  # Show first 64 bytes
                try:
                    decoded = content.decode('ascii', errors='ignore')
                    if 'flag' in decoded.lower():
                        print(f"[!] Possible flag in memory: {decoded}")
                except:
                    pass

    finally:
        # Cleanup
        if original_tmp:
            os.environ['TMPDIR'] = original_tmp
        shutil.rmtree(tmp_dir)

def main():
    script_path = "ctf_files/welcome2.r2"
    print("[+] Starting r2 script monitoring...")
    monitor_execution(script_path)

if __name__ == '__main__':
    main()
